using Reforged.App.Models; using Reforged.Server;
namespace Reforged.App.Services;
public sealed class ReforgedHostController(IAppLogger logger) : IReforgedHostController { private readonly SemaphoreSlim _gate=new(1,1); private CancellationTokenSource? _runCts; private Task? _runTask; private ServerRuntimeHost? _host; public HostControllerState State{get;private set;}=HostControllerState.Stopped; public string StatusMessage{get;private set;}="Stopped"; public int ConnectedSessionCount=>_host?.Sessions.ActiveSessionCount??0; public event EventHandler? StateChanged; public async Task StartAsync(HostLaunchOptions options,CancellationToken token){await _gate.WaitAsync(token);try{if(State is HostControllerState.Starting or HostControllerState.Running)throw new InvalidOperationException("A Host instance is already active.");Set(HostControllerState.Starting,"Starting");var bootstrap=new ServerBootstrap().Run(options.ProjectRoot);if(!bootstrap.Passed||bootstrap.ProjectRoot is null)throw new InvalidOperationException($"Host bootstrap failed with {bootstrap.ErrorCount} error(s).");var configured=ServerRuntimeOptions.Load(bootstrap.ProjectRoot);var runtimeOptions=new ServerRuntimeOptions{HostName=configured.HostName,DefaultWorldId=options.WorldId??configured.DefaultWorldId,WorldTickMilliseconds=configured.WorldTickMilliseconds,CombatTickMilliseconds=configured.CombatTickMilliseconds,Development=configured.Development,Worlds=configured.Worlds,Network=new NetworkRuntimeOptions{Enabled=true,BindAddress=options.BindAddress,TelnetPort=options.Port,MaxSessions=options.MaximumSessions,LoginTimeoutSeconds=configured.Network.LoginTimeoutSeconds,AllowWorldSelection=configured.Network.AllowWorldSelection}};_host=new ServerRuntimeHost(bootstrap.ProjectRoot,runtimeOptions);_host.Bootstrap();_runCts=CancellationTokenSource.CreateLinkedTokenSource(token);_runTask=_host.RunNetworkAsync(_runCts.Token);_=_runTask.ContinueWith(t=>{if(t.IsFaulted)Set(HostControllerState.Failed,t.Exception?.GetBaseException().Message??"Host failed");else if(State!=HostControllerState.Stopping)Set(HostControllerState.Stopped,"Stopped");},TaskScheduler.Default);Set(HostControllerState.Running,$"Running on {options.BindAddress}:{options.Port}");logger.Info("Embedded Host started.");}catch(Exception e){Set(HostControllerState.Failed,e.Message);logger.Error("Embedded Host start failed.",e);throw;}finally{_gate.Release();}} public async Task StopAsync(CancellationToken token){await _gate.WaitAsync(token);try{if(State==HostControllerState.Stopped)return;Set(HostControllerState.Stopping,"Stopping");_runCts?.Cancel();if(_runTask is not null){try{await _runTask.WaitAsync(TimeSpan.FromSeconds(15),token);}catch(OperationCanceledException){}catch(TimeoutException){logger.Error("Host did not stop within the graceful shutdown window.");}}_runCts?.Dispose();_runCts=null;_runTask=null;_host=null;Set(HostControllerState.Stopped,"Stopped");logger.Info("Embedded Host stopped.");}finally{_gate.Release();}} public async Task RestartAsync(HostLaunchOptions o,CancellationToken t){await StopAsync(t);await StartAsync(o,t);} private void Set(HostControllerState s,string m){State=s;StatusMessage=m;StateChanged?.Invoke(this,EventArgs.Empty);} }
